void NPC_ERR_DiSP(int meindex,int talker,int errNO)
{
	char token[1024];
	int i=0;
	int otherindex;
	int fd = getfdFromCharaIndex( talker);
	char npcarg[NPC_UTIL_GETARGSTR_BUFSIZE - 1024 * 20];

	if(NPC_Util_GetArgStr( meindex, npcarg, sizeof(npcarg))==NULL){
